#define is_sublist_parent(ssep) (ss_entry_kind(ssep) == iek_src_seq_sublist)


/*
The following variables indicate the context in which a name or expression
is being generated.
*/
static a_boolean
		in_friend_declaration;
			/* TRUE if the name being generated appears within
			   a friend declaration's parameter list. */
static a_boolean
		in_ctor_default_argument;
			/* TRUE if the expression being generated appears
			   in the default argument of a constructor
			   parameter (needed to work around a Microsoft 6.0
			   bug). */
static a_boolean
		in_generated_instance;
			/* TRUE if the expression being generated appears
			   in a generated instance of a function template. */

/*
Entry used to record an adjustment needed at the end of a name context,
i.e., restoring the previous values of the qualification_needed and/or
elaborated_type_specifier_needed flags of an IL entity, which were changed
when the entity's name was hidden at the start of the name context.
*/
typedef struct a_hidden_name_fixup *a_hidden_name_fixup_ptr;
typedef struct a_hidden_name_fixup {
  a_hidden_name_fixup_ptr
		next;	/* Next fixup on the list, or NULL if this is the
			   last entry. */
  a_bit_field	qualification_needed:1;
  a_bit_field	elaborated_type_specifier_needed:1;
  a_bit_field	partially_hidden_by_microsoft_injected_class_name:1;
  a_bit_field	visible_as_unqualified_name:1;
			/* Flag values to restore. */
  a_tagged_pointer
		entity;	/* Pointer to the entity to be fixed up. */
} a_hidden_name_fixup;


static a_hidden_name_fixup_ptr
		avail_hidden_name_fixups;
			/* List of hidden-name-fixup entries that have been
			   freed and are available for reuse. */

/*
Entry used in a stack to indicate the name contexts we are currently
inside of.  This is used to avoid adding class qualifiers to names when
they are not necessary.
*/
typedef struct a_name_context *a_name_context_ptr;
typedef struct a_name_context {
  a_name_context_ptr
		next;	/* The name context outside of this one, or NULL
			   if there are no more. */
  a_scope_ptr	assoc_scope;
			/* The scope that defines the name context.
			   NULL when class_type is a nonreal class. */
  a_type_ptr	class_type;
			/* A class that defines the name context.  NULL
			   if not applicable (assoc_scope is non-NULL in
			   that case). */
  a_type_ptr	class_type_for_access_not_naming;
			/* If non-NULL, indicates a class that we are within
			   for access purposes but not for naming purposes,
			   e.g., because we are in the type specifiers of
			   a definition of a class member. */
  an_access_specifier
		access;	/* When putting out a class, the current default
			   access for a member declaration. */
#if MICROSOFT_EXTENSIONS_ALLOWED
  an_access_specifier
		assembly_access;	
			/* When putting out a class, the current default
			   assembly access for a member declaration. */
#endif /* MICROSOFT_EXTENSIONS_ALLOWED */
  a_hidden_name_fixup_ptr
		fixups;	/* Hidden-name fixups to be done at the end of the
			   name context. */
  a_byte_boolean
		invisible_to_cfront;
			/* TRUE if this context is not visible to cfront
			   (due to a bug), and should not be used to remove
			   class qualifiers from name references. */
  a_byte_boolean
		field_selection_context;
			/* TRUE if this context was pushed for the right
			   operand of a field selection. */
  a_byte_boolean
		saved_in_class_scope_with_dependent_base;
			/* The value of the global variable
			   in_class_scope_with_dependent_base to be restored
			   when this context is popped off the stack. */
  a_byte_boolean
		has_dependent_base;
			/* TRUE if this scope is associated with the
			   prototype instantiation of a class template with
			   dependent bases.  (For efficiency, this will only
			   be set to TRUE if the target compiler searches
			   dependent bases during unqualified lookup.) */
} a_name_context;

static a_name_context_ptr
		curr_name_context;
			/* Current name context stack. */

static a_name_context_ptr
		avail_name_contexts;
			/* List of name context entries that have been freed
			   and are available for reuse. */

static a_boolean
		in_class_scope_with_dependent_base;
			/* TRUE if there is a prototype instantiation class
			   on the stack that has a dependent base.  Used so
			   that references to names that are not part of
			   the current instantiation can be qualified when
			   generating code for compilers that do not
			   exclude dependent bases from unqualified name
			   lookup in the instantiated class.  (For
			   efficiency, this will only be set to TRUE if the
			   target compiler searches dependent base classes
			   during unqualified name lookup.) */

/*
Return TRUE if the target compiler searches dependent base classes when
doing unqualified name lookup.
*/
#define target_compiler_searches_dep_bases() \
  (gcc_or_clang_is_generated_code_target || msvc_is_generated_code_target)

/*
Return TRUE if the current name context is a class.
*/
#define curr_name_context_is_a_class()                                \
  (curr_name_context->class_type != NULL)

/*
Given that the current name context is a class, return the class type.
*/
#define curr_name_context_class() (curr_name_context->class_type)


/*
Macro to test a type kind to see if it is a class, struct, or union.
*/
#define is_class_type_kind(kind)                                      \
  ((kind) == (a_type_kind)tk_class  ||                                \
   (kind) == (a_type_kind)tk_struct ||                                \
   (kind) == (a_type_kind)tk_union)

/*
Flags for gen_name:
*/
typedef int a_gen_name_options_set;
#define GN_NO_OPTIONS 0
#define GN_FORCE_QUALIFIED_NAME 0x1
			/* Force use of a qualified name even if one
			   is not required in the current context. */
#define GN_DECLARATION 0x2
			/* This use of the name is a declaration or
			   definition, rather than a use. */
#define GN_PARENS_IF_GLOBAL_QUALIFIER 0x4
			/* Put parentheses around the name if it begins
			   with a "::" global qualifier. */
#define GN_QUALIFIER 0x8
			/* gen_name is invoked recursively to generate a
			   qualifier for a qualified name (e.g., "A::B" in
			   "A::B::x"). */
#define GN_BOUND_MEMBER 0x10
			/* gen_name is invoked to emit the name of a member
			   (the name of the flag is historical; it also
			   applies to names in using-declarations).  When
			   generating code for Microsoft versions before 7.0,
			   such a name cannot be qualified with a namespace
			   name. */
#define GN_DEPENDENT 0x20
			/* The name to generate depends on a template
			   parameter. */
#define GN_NO_TEMPLATE_ARGS 0x40
			/* Do not generate the template arguments. */
#define GN_TEMPLATE 0x80
			/* The name to generate is that of a template. */
#define GN_BASE_SPECIFIER 0x100
			/* The name is used in a base specifier list. */
#define GN_USING_DIRECTIVE 0x200
			/* The name is the namespace nominated by a
			   using-directive. */
#define GN_ALLOW_PROTECTED_BASE_MEMBER_QUALIFIED_NAME 0x400
			/* Allow the use of the base class name when forming
			   a qualified name referring to a protected member of
			   a base of the current class context. */
#define GN_SUPPRESS_TEMPLATE_KEYWORD 0x800
			/* Do not put out the "template" keyword in a
			   qualifier (used to work around a g++ bug that
			   issues errors when the "template" keyword is not
			   strictly needed). */
#define GN_FRIEND_DECL 0x1000
			/* Used with GN_DECLARATION to indicate that the
			   name being declared is in a "friend"
			   declaration. */
#define GN_PTR_TO_DATA_MEMBER 0x2000
			/* The name is the qualifier in a pointer to data
			   member type. */
#define GN_ELAB_TYPE_SPEC_AS_DECL 0x4000
			/* The name is part of an elaborated-type-specifier
			   that is used as a declaration. */

/*
The alignment specified by the most recent #pragma pack directive (0
indicates the default value).
*/
static a_targ_alignment
		curr_pack_alignment;
/*
The following variable is TRUE if a #pragma pack directive was constructed for
a particular class definition and indicates that the previous alignment must
be restored.
*/
static a_boolean
		need_pragma_pack_restore;

#if GENERATE_LINKAGE_SPEC_BLOCKS
/*
A variable that reflects the current default name linkage ("C++" by default
in C++ mode, and modified when extern "..." { ... } blocks are emitted).
*/
static a_name_linkage_kind
		curr_default_name_linkage;
#endif /* GENERATE_LINKAGE_SPEC_BLOCKS */

/*
If e is an enk_constant node and the constant has an associated expression
(backing expression or template parameter expression) that will be put out,
return that expression; otherwise return e.
*/
#define assoc_expr_if_constant(e)                                             \
  ((is_constant_node(e) &&                                                    \
    constant_should_be_put_out_as_expr(node_constant(e))) ?                   \
                                        node_constant(e)->expr :              \
   (is_constant_node(e) &&                                                    \
    node_constant(e)->kind == (a_constant_repr_kind)ck_template_param &&      \
    node_constant(e)->variant.template_param.kind ==                          \
                          (a_template_param_constant_kind)tpck_expression) ?  \
                     expr_node_from_tpck_expression(node_constant(e)) : (e))


